import numpy as np

def build_model():
    # Hidden state factors: position (controlled), mode, flag
    factors = [
        ("position", 4, True),   # 0,1,2,3 - controlled by actions
        ("mode", 2, False),      # 0->mode1(o1=1), 1->mode2(o1=2)
        ("flag", 2, False),      # 0->o2=1, 1->o2=2
    ]

    # Observation mappings
    # o0 = position (deterministic)
    A0 = np.zeros((4, 4))
    for s in range(4):
        A0[s, s] = 1.0

    # o1 depends on position and mode
    # pos 0,3 -> o1=0; pos 1,2 -> mode (1 or 2)
    A1 = np.zeros((3, 4, 2))
    for pos in range(4):
        for m in range(2):
            mode_val = m + 1  # 1 or 2
            if pos == 0 or pos == 3:
                A1[0, pos, m] = 1.0
            else:
                A1[mode_val, pos, m] = 1.0

    # o2 depends on position and flag
    # pos !=3 -> o2=0; pos 3 -> flag+1 (1 or 2)
    A2 = np.zeros((3, 4, 2))
    for pos in range(4):
        for f in range(2):
            if pos == 3:
                A2[f+1, pos, f] = 1.0
            else:
                A2[0, pos, f] = 1.0

    A = [A0, A1, A2]
    A_deps = [[0], [0, 1], [0, 2]]

    # Position transitions (controlled, size 4)
    B_pos = np.zeros((4, 4, 4))  # next, current, action
    for s in range(4):
        for a in range(4):
            if a == 0:  # stay at 1,2; 3->0; 0->0
                if s == 3:
                    B_pos[0, s, a] = 1.0
                else:
                    B_pos[s, s, a] = 1.0
            elif a == 1:  # right: 0->1, else stay
                if s == 0:
                    B_pos[1, s, a] = 1.0
                else:
                    B_pos[s, s, a] = 1.0
            elif a == 2:  # down: 0->2, else stay
                if s == 0:
                    B_pos[2, s, a] = 1.0
                else:
                    B_pos[s, s, a] = 1.0
            elif a == 3:  # jump to 3 from 0, else stay
                if s == 0:
                    B_pos[3, s, a] = 1.0
                else:
                    B_pos[s, s, a] = 1.0

    # Mode: never changes (identity)
    B_mode = np.zeros((2, 2, 1))
    for m in range(2):
        B_mode[m, m, 0] = 1.0

    # Flag: never changes (identity)
    B_flag = np.zeros((2, 2, 1))
    for f in range(2):
        B_flag[f, f, 0] = 1.0

    B = [B_pos, B_mode, B_flag]

    # Initial: pos=0, mode uniform {0,1}, flag uniform {0,1}
    D_pos = np.zeros(4)
    D_pos[0] = 1.0
    D_mode = np.array([0.5, 0.5])
    D_flag = np.array([0.5, 0.5])
    D = [D_pos, D_mode, D_flag]

    return {
        "factors": factors,
        "A": A,
        "A_deps": A_deps,
        "B": B,
        "D": D
    }
